            using (KasabaKIATEntities db = new KasabaKIATEntities())
            {
                var query = from list in db.tbbu_profil_lager
                            where list.YEAR_FIN == year &&
                            list.KVARTAL == kvartal &&
                            list.DEPARTMENT_BASE == departmentBase &&
                            list.REPORT_TYPE == (int)ReportType.Lager
